class Solution:
    def searchMatrix(self, matrix: list[list[int]], target: int) -> bool:
        if not matrix or not matrix[0]:
            return False

        rows, cols = len(matrix), len(matrix[0])
        # 从右上角开始：它是所在行的最大值、所在列的最小值
        r, c = 0, cols - 1

        while r < rows and c >= 0:
            val = matrix[r][c]
            if val == target:
                return True
            if val > target:
                c -= 1  # 当前列下方的值都更大，排除整列
            else:
                r += 1  # 当前行左方的值都更小，排除整行

        return False
